         let mut tree = RenderTree::default();

         let mut a = vstack![text("ab")]
             .spacing(4.0)
             .padding(8.0)
             .build();
         assign_ids(&mut a, &mut 1);
         {
             let mut guest = Guest::new(&mut mem, &layout);
             guest.begin_frame();
             engine.emit(&a, &mut guest).unwrap();
             guest.end_frame();
