    rc::Rc,
    string::{String, ToString},
};
use core::fmt;
use core::num::NonZeroUsize;
use core::ops::{Add, AddAssign};
use fmt::Display;

use nami::signal::{IntoComputed, IntoSignal};
use nami::{Binding, Computed, Signal, SignalExt};
use waterui_core::configurable;
use waterui_core::layout::HorizontalAlignment;
use waterui_core::{Environment, View, flatten_signal};
use waterui_graphics::color::Color;
use waterui_locale::{Locale, TranslationCatalog, locale_binding};
use waterui_str::Str;

use crate::font::FontWeight;
use crate::{font::Font, styled::StyledStr};

type ConfigResolver = dyn Fn(&Environment) -> Computed<TextConfig>;

/// Formats signal values for [`Text::format`].
pub trait Formatter<T>: Clone {
    /// Formats one signal value.
    fn format(&self, value: &T) -> Str;
}

/// Native text payload consumed by platform backends.
#[derive(Debug, Clone)]
#[non_exhaustive]
pub struct TextConfig {
    /// The rich text content to be displayed.
    pub content: Computed<StyledStr>,
    /// Paragraph alignment for multiline layout.
    pub paragraph_alignment: Computed<HorizontalAlignment>,
    /// Maximum number of laid-out lines, or `None` for no limit.
    ///
    /// Text that does not fit the limit is truncated at its last visible
    /// line — with a trailing ellipsis where the backend's native text
    /// machinery provides one. This is `SwiftUI`'s `lineLimit`: a control
    /// label capped at one line stays a label under compression instead of
    /// folding into a paragraph.
    pub line_limit: Option<NonZeroUsize>,
}

impl TextConfig {
    /// Creates a raw text config from styled content.
    #[must_use]
    pub fn new(content: impl IntoComputed<StyledStr>) -> Self {
        Self {
            content: content.into_signal().map(StyledStr::from).computed(),
            paragraph_alignment: Computed::constant(HorizontalAlignment::Leading),
            line_limit: None,
        }
    }
}

configurable!(
    /// Raw styled text view.
    RawText,
    TextConfig
);

#[derive(Clone)]
enum TextKind {
    Raw(TextConfig),
    Signal { resolver: Rc<ConfigResolver> },
}

