/// Installs a signal subscription before taking its initial snapshot.
pub fn subscribe_then_get<S>(
    signal: &S,
    watcher: impl Fn(Context<S::Output>) + 'static,
) -> (S::Output, S::Guard)
where
    S: Signal,
{
    let guard = signal.watch(watcher);
    (signal.get(), guard)
}

