    /// Resolve the container to a virtualizable stack axis (spacing +
    /// cross-axis alignment) when it is a `VStack`/`HStack`, unwrapping the
    /// direction-mirror layer that [`View::body`](Self::body) installs.
    ///
    /// The lazy path keeps the concrete stack layout visible so
    /// [`crate::stack::lazy_stack_axis`] can read it; the fixed path wraps it in
    /// `DirectionalLayout` for RTL mirroring. Backends that need the axis from a
    /// fixed container read it here instead of duplicating that unwrap.
    #[must_use]
    pub fn stack_axis(&self) -> Option<crate::stack::LazyStackAxis> {
        let layout: &dyn Layout = match self.layout.as_ref().downcast_ref::<DirectionalLayout>() {
            Some(direction) => direction.inner.as_ref(),
            None => self.layout.as_ref(),
        };
        crate::stack::lazy_stack_axis(layout)
    }
}

