//! The single application logic: author a view and project it through the
//! Pathland opcode protocol. Each entry point decodes the stream for its own
//! backend only.

use pathland_core_transport::FrameSource;
use pathland_waterui::Emitter;
use waterui::prelude::*;

/// The view authored by the application (the protocol's guest side).
pub fn source() -> impl View {
    vstack((
        text("Pathland round-trip"),
        text("This screen was serialized to 16-byte Pathland opcodes,"),
        text("transported, decoded, and rendered by the selected backend."),
        spacer(),
        hstack((button("Hello"), button("World"))),
    ))
}

/// Serialize `view` to Pathland opcodes, returning the emitter (which owns the
/// shared ring) and the root node id.
pub fn emit(view: impl View) -> (Emitter, u32) {
    let env = Environment::new();
    let mut emitter = Emitter::new();
    let root = emitter.emit(view, &env).expect("emit opcodes");
    (emitter, root)
}

/// Drain the emitter's frames into `sink`, which decodes them for its backend.
pub fn decode<S>(emitter: &Emitter, sink: &mut S)
where
    S: FnMut(&pathland_core::Frame<'_>),
{
    let transport = emitter.transport();
    let mut borrow = transport.borrow_mut();
    while let Ok(Some(batch)) = borrow.next_frame() {
        sink(batch.frame());
    }
}

//! Pathland round-trip (macOS backend).
//!
//! The single application logic lives in [`roundtrip`]; this entry point decodes
//! the opcode stream into WaterUI views and renders them through WaterUI's
//! platform backend (AppKit on macOS). Run with `water run --platform macos`.

pub mod roundtrip;

use pathland_waterui::Consumer;
use waterui::app::App;
use waterui::prelude::*;

fn main() -> impl View {
    let (emitter, root) = roundtrip::emit(roundtrip::source());

    let mut consumer = Consumer::new();
    roundtrip::decode(&emitter, &mut |frame| consumer.apply(frame));

    consumer.rebuild(root).expect("rebuild view tree")
}

pub fn app(env: Environment) -> App {
    App::new(main, env)
}

waterui_ffi::export!();

//! Pathland round-trip (HTML backend).
//!
//! The single application logic lives in [`pathland_roundtrip::roundtrip`];
//! this entry point decodes the opcode stream into an HTML document and prints
//! it to the console. Run with `cargo run --bin html`.

use pathland_render_html::HtmlRenderer;
use pathland_roundtrip::roundtrip;

fn main() {
    let (emitter, root) = roundtrip::emit(roundtrip::source());

    let mut renderer = HtmlRenderer::new();
    roundtrip::decode(&emitter, &mut |frame| renderer.apply(frame));

    println!("{}", renderer.render(root));
}

