function encodeEvent(target) {
    // batch with one EVENT opcode (PointerUp)
    const opcodes = new Uint8Array(16);
    const view = new DataView(opcodes.buffer);
    view.setUint8(0, CAT_EVENT);
    view.setUint8(1, POINTER_UP);
    // flags 2-3 = 0
