    // b, c = 0
    const header = new Uint8Array(16);
    const hv = new DataView(header.buffer);
    hv.setUint32(0, 0x504C504C, true);  // magic "PLPL"
    hv.setUint16(4, 1, true);  // version
    hv.setUint16(6, 1, true);  // flags = HOST_TO_GUEST
    hv.setUint32(8, 0, true);  // frameCount
    hv.setUint32(12, 1, true);  // opcodeCount
    // arenaDeltaLen = 0 (4 bytes)
    const out = new Uint8Array(16 + 16 + 4);
    out.set(header, 0);
    out.set(opcodes, 16);
    return out;
}
