    fn set_property(&mut self, id: u32, prop: u16, value_type: u8, value: u32) {
        self.opcodes.push(Opcode::new(category::STYLE, style::SET_PROPERTY, 0, id, ((value_type as u32) << 16) | prop as u32, value));
