        self.strings.extend_from_slice(&(text.len() as u32).to_le_bytes());
        self.strings.extend_from_slice(text.as_bytes());
        self.opcodes.push(Opcode::new(category::STYLE, style::SET_TEXT, 0, id, offset, 0));
    }
}
