//! Pathland web demo server.
//!
//! SSRs a WaterUI view to HTML (with `data-pathland-id` for hydration), then
//! streams live opcode deltas to the browser over WebSocket and dispatches
//! inbound input events back into the app. The app state (a counter) is driven
//! by both a server-side timer and button clicks.
//!
//! Deltas are **self-contained**: each WebSocket message is one frame's opcodes
//! plus its own string section, so no aggregation, no snapshot, and nothing is
//! sent on connect — the browser renders the initial state from the SSR HTML.

use std::cell::{Cell, RefCell};
use std::rc::Rc;
use std::time::Duration;

use axum::Router;
use axum::extract::State;
use axum::extract::ws::{Message, WebSocket, WebSocketUpgrade};
use axum::response::{Html, Response};
use axum::routing::get;
use bytes::Bytes;
use pathland_core::{Event, Opcode};
use pathland_core_transport::{decode_events, encode_frame};
use pathland_render_html::HtmlRenderer;
use pathland_waterui::Emitter;
use waterui_controls::button::button;
use waterui_core::{Binding, Computed, Environment, SignalExt, View, binding};
use waterui_layout::stack::vstack;
use waterui_text::text::text;

/// The application view (shared by the native and web demos).
fn counter_view(count: Binding<i32>) -> impl View {
    let label: Computed<String> = count.map(|c| format!("Count: {c}")).computed();
    vstack((
        text("Pathland web"),
        text(label),
        button("Increment").action({
            let c = count.clone();
            move || {
                c.set(c.get() + 1);
            }
        }),
    ))
}

/// Send + Sync state handed to axum handlers.
#[derive(Clone)]
struct AppState {
    html_rx: tokio::sync::watch::Receiver<String>,
    batch_tx: tokio::sync::broadcast::Sender<Bytes>,
    event_tx: tokio::sync::mpsc::UnboundedSender<Event>,
}

fn main() {
    let rt = tokio::runtime::Builder::new_current_thread()
        .enable_all()
        .build()
        .expect("runtime");
    let local = tokio::task::LocalSet::new();
    local.block_on(&rt, run());
}

async fn run() {
    let env = Environment::new();
    let count: Binding<i32> = binding(0);
    let view = counter_view(count.clone());

    let (batch_tx, _) = tokio::sync::broadcast::channel::<Bytes>(64);
    let (html_tx, html_rx) = tokio::sync::watch::channel::<String>(String::new());
    let (event_tx, mut event_rx) = tokio::sync::mpsc::unbounded_channel::<Event>();

    // Actor-local retained render state (WaterUI state is `!Send`).
    let html = Rc::new(RefCell::new(HtmlRenderer::new()));
    let root = Rc::new(Cell::new(0u32));

    let sink = {
        let html = Rc::clone(&html);
        let root = Rc::clone(&root);
        let batch_tx = batch_tx.clone();
        let html_tx = html_tx.clone();
        move |opcodes: Vec<Opcode>, strings: Vec<u8>| {
            // 1. apply the frame to the retained HTML tree (SSR state)
            html.borrow_mut().apply(&opcodes, &strings);
            // 2. encode the self-contained frame and broadcast to WS clients
            let batch = encode_frame(&opcodes, &strings);
            let _ = batch_tx.send(Bytes::from(batch));
            // 3. re-render the SSR HTML once the root is known
            let r = root.get();
            if r != 0 {
                let rendered = html.borrow().render(r);
                let _ = html_tx.send(rendered);
            }
        }
    };

    let mut emitter = Emitter::with_sink(sink);
    let root_id = emitter.emit(view, &env);
    root.set(root_id);
    let rendered = html.borrow().render(root_id);
    let _ = html_tx.send(rendered);

    // Single-threaded app actor: server timer + inbound input events.
    tokio::task::spawn_local(async move {
        let mut ticker = tokio::time::interval(Duration::from_secs(1));
        ticker.tick().await; // discard the immediate tick
        loop {
            tokio::select! {
                _ = ticker.tick() => {
                    count.set(count.get() + 1);
                }
                Some(event) = event_rx.recv() => {
                    if let Event::PointerUp { target, .. } = event {
                        emitter.invoke(target, &env);
                    }
                }
            }
        }
    });

    let state = AppState {
        html_rx,
        batch_tx,
        event_tx,
    };
    let app = Router::new()
        .route("/", get(index))
        .route("/app.js", get(app_js))
        .route("/ws", get(ws_handler))
        .with_state(state);

    let listener = tokio::net::TcpListener::bind("127.0.0.1:3000")
        .await
        .expect("bind");
    axum::serve(listener, app).await.expect("serve");
}

async fn index(State(state): State<AppState>) -> Html<String> {
    Html(state.html_rx.borrow().clone())
}

async fn app_js() -> &'static str {
    include_str!("../static/app.js")
}

async fn ws_handler(ws: WebSocketUpgrade, State(state): State<AppState>) -> Response {
    ws.on_upgrade(move |socket| handle_socket(socket, state))
}

async fn handle_socket(mut socket: WebSocket, state: AppState) {
    let mut batch_rx = state.batch_tx.subscribe();
    let event_tx = state.event_tx;

    loop {
        tokio::select! {
            msg = socket.recv() => {
                match msg {
                    Some(Ok(Message::Binary(data))) => {
                        if let Ok((_, events)) = decode_events(&data) {
                            for event in events {
                                let _ = event_tx.send(event);
                            }
                        }
                    }
                    Some(Ok(Message::Close(_))) | None => break,
                    _ => {}
                }
            }
            batch = batch_rx.recv() => {
                match batch {
                    Ok(bytes) => {
                        if socket.send(Message::Binary(bytes)).await.is_err() {
                            break;
                        }
                    }
                    Err(_) => break,
                }
            }
        }
    }
}

// Pathland web client: hydrate the SSR HTML, apply self-contained opcode
// deltas, send events. Each batch carries its own string section, so no arena
// mirror is needed.

const CAT_STYLE = 2;
const CMD_SET_TEXT = 3;
const CAT_EVENT = 3;
const CMD_POINTER_UP = 3;

// Hydrate the server-rendered DOM: node id -> element.
const byId = new Map();
for (const el of document.querySelectorAll("[data-pathland-id]")) {
    byId.set(Number(el.getAttribute("data-pathland-id")), el);
}

// Read a length-prefixed string (`[u32 len][bytes]`) at a relative offset.
function readString(strings, offset) {
    const view = new DataView(strings.buffer, strings.byteOffset, strings.byteLength);
    const len = view.getUint32(offset, true);
    const bytes = strings.subarray(offset + 4, offset + 4 + len);
    return new TextDecoder().decode(bytes);
}

function applyBatch(bytes) {
    const view = new DataView(bytes.buffer, bytes.byteOffset, bytes.byteLength);
    const opcodeCount = view.getUint32(12, true);
    const opcodesEnd = 16 + opcodeCount * 16;
    const stringsLen = view.getUint32(opcodesEnd, true);
    const stringsStart = opcodesEnd + 4;
    const strings = bytes.subarray(stringsStart, stringsStart + stringsLen);

    for (let i = 0; i < opcodeCount; i++) {
        const pos = 16 + i * 16;
        const category = view.getUint8(pos);
        const command = view.getUint8(pos + 1);
        const a = view.getUint32(pos + 4, true);
        const b = view.getUint32(pos + 8, true);
        if (category === CAT_STYLE && command === CMD_SET_TEXT) {
            const el = byId.get(a);
            if (el) el.textContent = readString(strings, b);
        }
    }
}

// Encode a single PointerUp EVENT opcode as a host -> guest batch.
function encodePointerUp(target) {
    const out = new Uint8Array(16 + 16 + 4);
    const header = new DataView(out.buffer);
    header.setUint32(0, 0x504c504c, true); // magic "PLPL"
    header.setUint16(4, 1, true); // version
    header.setUint16(6, 1, true); // flags = HOST_TO_GUEST
    header.setUint32(8, 0, true); // frameCount
    header.setUint32(12, 1, true); // opcodeCount
    const op = new DataView(out.buffer, 16);
    op.setUint8(0, CAT_EVENT);
    op.setUint8(1, CMD_POINTER_UP);
    op.setUint32(4, target, true); // a = target node id
    return out;
}

const ws = new WebSocket(`ws://${location.host}/ws`);
ws.binaryType = "arraybuffer";
ws.onmessage = (event) => applyBatch(new Uint8Array(event.data));

document.addEventListener("click", (event) => {
    const button = event.target.closest("button[data-pathland-id]");
    if (!button || ws.readyState !== WebSocket.OPEN) return;
    const target = Number(button.getAttribute("data-pathland-id"));
    ws.send(encodePointerUp(target));
});

